document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("hamburger"),t=document.getElementById("navLinks"),n=document.querySelector(".header");e?.addEventListener("click",()=>{e.classList.toggle("active"),t?.classList.toggle("active"),e.setAttribute("aria-expanded",e.classList.contains("active").toString())}),window.addEventListener("scroll",()=>{window.pageYOffset>100?n?.classList.add("shadow-lg"):n?.classList.remove("shadow-lg")}),document.addEventListener("click",s=>{!e?.contains(s.target)&&!t?.contains(s.target)&&(e?.classList.remove("active"),t?.classList.remove("active"))})});
